SELECT p.*, u.nickname, (SELECT count(postno) FROM comments c WHERE c.postno = p.postno ) AS count_comments, (SELECT count(userid) FROM post_likes l WHERE l.postno = p.postno ) AS count_likes FROM POSTS p LEFT JOIN USERS u ON (p.writer = u.userid)
board_type = #{boardType, jdbcType=VARCHAR}
AND p.postno = #{postNo, jdbcType=NUMERIC}
AND writer = #{writer, jdbcType=VARCHAR}
AND report_yn = 1
ORDER BY notice_yn DESC, p.created_at DESC

